 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    activated_sixes = set()

    # Join diagonal pairs of 1 markers. Any 6 lying on the connector activates
    # a full diagonal of 6s perpendicular to that connector.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc) or dr == 0:
                continue
            sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
            for k in range(abs(dr) + 1):
                r, c = r1 + sr * k, c1 + sc * k
                if grid[r][c] == 6:
                    activated_sixes.add((r, c))
                elif grid[r][c] == 4:
                    out[r][c] = 1

    # Extend each activated 6 along both directions of the perpendicular diagonal.
    for r0, c0 in activated_sixes:
        for slope in (-1, 1):
            # For connector slope sc/sr, perpendicular slope is its negative.
            # Here a diagonal line is defined by c-r or c+r being constant.
            for step in (-1, 1):
                r, c = r0 + step, c0 + slope * step
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] == 4:
                        out[r][c] = 6
                    r += step
                    c += slope * step
    return out
