from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    activated = set()

    # Join diagonal 1 markers. A 6 on the segment projects a perpendicular
    # diagonal of 6s across the grid.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue
            sr, sc = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
            perpendicular = -sc * sr
            for k in range(abs(dr) + 1):
                r, c = r1 + sr * k, c1 + sc * k
                if grid[r][c] == 6:
                    activated.add((r, c, perpendicular))
                elif grid[r][c] == bg:
                    out[r][c] = 1

    for r0, c0, slope in activated:
        for step in (-1, 1):
            r, c = r0 + step, c0 + slope * step
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] == bg:
                    out[r][c] = 6
                r += step
                c += slope
    return out

